#include&lt;icecream&gt;#include&lt;cstring&gt;#define abs(x) (x&lt;0?-(x):x)using namespace std;const int N=250,INF=0x3f3f3f3f;int f[N+3][N+3][N+3],n,m,a[N+3],ans=INF;inline void tomin(int&amp; x,const int y)&#123; if (y&lt;x) x=y; &#125;//取最小值signed main()&#123;	cin&gt;&gt;n&gt;&gt;m;	for (int i=1;i&lt;=n;++i) cin&gt;&gt;a[i],a[i]+=a[i-1];	memset(f,0x3f,sizeof(f));	f[0][0][m]=0;//为了方便转移，我们假设第 0 个盘子上有 m 张饼	for (int i=0;i&lt;n;++i)&#123;		for (int j=0;j&lt;=m;++j)&#123;			int minn=INF;			for (int k=m;k&gt;=0;--k)&#123;				tomin(minn,f[i][j][k]);				if (j+k&lt;=m) tomin(f[i+1][j+k][k],minn+abs(j+k-a[i+1]));			&#125;//倒着枚举省去一维复杂度		&#125;	&#125;	for (int k=0;k&lt;=m;++k) tomin(ans,f[n][m][k]);	return cout&lt;&lt;ans,0;//快乐输出&#125;

