#include &lt;bits/stdc++.h&gt;namespace fastio &#123;    // tested (integer, string and char only)    template&lt;size_t BF_SIZE&gt;    class FastIO &#123;    private:        char inbuf[BF_SIZE];        char outbuf[BF_SIZE];        char intStr[64];        size_t l = 0;        size_t r = 0;        size_t outidx = 0;    public:        ~FastIO() &#123;            flush();        &#125;        static inline bool isNspace(char c) &#123;            return !isspace(c);        &#125;        inline char gc() &#123;            if (l &gt;= r) &#123;                l = 0;                r = fread(inbuf, 1, BF_SIZE, stdin);            &#125;            if (l &lt; r) &#123;                return inbuf[l++];            &#125;            return EOF;        &#125;        template&lt;typename Int&gt;        inline void getInt(Int&amp; x) &#123;            x = 0; bool p = 0; char ch = gc();            while (!isdigit(ch)) p |= (ch == &#x27;-&#x27;), ch = gc();            while (isdigit(ch)) x = (x &lt;&lt; 1) + (x &lt;&lt; 3) + (ch ^ &#x27;0&#x27;), ch = gc();            if (p) x = -x;        &#125;        template&lt;typename UInt&gt;        inline void getUInt(UInt&amp; x) &#123;            x = 0; char ch = gc();            while (!isdigit(ch)) ch = gc();            while (isdigit(ch)) x = (x &lt;&lt; 1) + (x &lt;&lt; 3) + (ch ^ &#x27;0&#x27;), ch = gc();        &#125;        inline void getChr(char&amp; c, std::function&lt;bool(char)&gt; mask = isNspace) &#123;            c = gc();            while (c != EOF &amp;&amp; !mask(c)) c = gc();        &#125;        inline void getStr(std::string&amp; s, std::function&lt;bool(char)&gt; mask = isNspace) &#123;            s.clear(); char ch = gc();            while (ch != EOF &amp;&amp; !mask(ch)) ch = gc();            while (ch != EOF &amp;&amp; mask(ch)) s += ch, ch = gc();        &#125;        inline void pc(char c) &#123;            outbuf[outidx++] = c;            if (outidx == BF_SIZE) flush();        &#125;        inline void putStr(const std::string&amp; s) &#123;            const char* sc = s.c_str();            size_t n = s.length();            size_t idx = 0;            while (idx &lt; n) &#123;                if (n - idx &lt;= BF_SIZE - outidx) memcpy(outbuf + outidx, sc + idx, n - idx), outidx += n - idx, idx = n;                else memcpy(outbuf + outidx, sc + idx, BF_SIZE - outidx), idx += BF_SIZE - outidx, outidx = BF_SIZE;                if (outidx == BF_SIZE) flush();            &#125;        &#125;        template&lt;typename Int&gt;        inline void putInt(Int x) &#123;            if (x &lt; 0) &#123;                pc(&#x27;-&#x27;);                x = -x;            &#125;            int idx = 0;            do &#123;                intStr[idx++] = &#x27;0&#x27; + x % 10;                x /= 10;            &#125; while (x);            for (--idx; idx &gt;= 0; --idx) &#123;                pc(intStr[idx]);            &#125;        &#125;        template&lt;typename UInt&gt;        inline void putUInt(UInt x) &#123;            int idx = 0;            do &#123;                intStr[idx++] = &#x27;0&#x27; + x % 10;                x /= 10;            &#125; while (x);            for (--idx; idx &gt;= 0; --idx) &#123;                pc(intStr[idx]);            &#125;        &#125;        inline void flush() &#123;            fwrite(outbuf, 1, outidx, stdout);            outidx = 0;        &#125;        // ---        FastIO&amp; operator &gt;&gt;(int&amp; other) &#123;            getInt(other);            return *this;        &#125;        FastIO&amp; operator &gt;&gt;(long long&amp; other) &#123;            getInt(other);            return *this;        &#125;        FastIO&amp; operator &gt;&gt;(short&amp; other) &#123;            getInt(other);            return *this;        &#125;        FastIO&amp; operator &gt;&gt;(__int128&amp; other) &#123;            getInt(other);            return *this;        &#125;        FastIO&amp; operator &gt;&gt;(unsigned int&amp; other) &#123;            getUInt(other);            return *this;        &#125;        FastIO&amp; operator &gt;&gt;(unsigned long long&amp; other) &#123;            getUInt(other);            return *this;        &#125;        FastIO&amp; operator &gt;&gt;(unsigned short&amp; other) &#123;            getUInt(other);            return *this;        &#125;        FastIO&amp; operator &gt;&gt;(unsigned __int128&amp; other) &#123;            getUInt(other);            return *this;        &#125;        FastIO&amp; operator &gt;&gt;(char&amp; other) &#123;            getChr(other);            return *this;        &#125;        FastIO&amp; operator &gt;&gt;(std::string&amp; other) &#123;            getStr(other);            return *this;        &#125;        // ---        FastIO&amp; operator &lt;&lt;(int other) &#123;            putInt(other);            return *this;        &#125;        FastIO&amp; operator &lt;&lt;(long long other) &#123;            putInt(other);            return *this;        &#125;        FastIO&amp; operator &lt;&lt;(__int128 other) &#123;            putInt(other);            return *this;        &#125;        FastIO&amp; operator &lt;&lt;(unsigned int other) &#123;            putUInt(other);            return *this;        &#125;        FastIO&amp; operator &lt;&lt;(unsigned long long other) &#123;            putUInt(other);            return *this;        &#125;        FastIO&amp; operator &lt;&lt;(unsigned short other) &#123;            putUInt(other);            return *this;        &#125;        FastIO&amp; operator &lt;&lt;(unsigned __int128 other) &#123;            putUInt(other);            return *this;        &#125;        FastIO&amp; operator &lt;&lt;(short other) &#123;            putInt(other);            return *this;        &#125;        FastIO&amp; operator &lt;&lt;(const std::string&amp; s) &#123;            putStr(s);            return *this;        &#125;        FastIO&amp; operator &lt;&lt;(char c) &#123;            pc(c);            return *this;        &#125;    &#125;;&#125;namespace bitree &#123;    // BIT template (tested)    template&lt;typename T&gt;    class BIT &#123;    private:        std::vector&lt;T&gt; tr;        int size;    public:        BIT(int n) : tr(n + 2, 0), size(n) &#123;&#125;        inline void add(int x, T v) &#123;            // add v to position x            assert(x &gt;= 0 &amp;&amp; x &lt;= size);            ++x;            for (; x &lt;= size + 1; x += x &amp; -x) tr[x] += v;        &#125;        inline T sum(int x) &#123;            // calculate the sum from 0 to x            assert(x &gt;= 0 &amp;&amp; x &lt;= size);            ++x;            T res = 0;            for (; x; x -= x &amp; -x) res += tr[x];            return res;        &#125;        inline T sum(int x, int y) &#123;            assert(x &gt;= 0 &amp;&amp; y &lt;= size);            if (x &gt; y) return 0;            return sum(y) - sum(x - 1);        &#125;        inline int kth(T v) &#123;            // if this is a count tree, find the kth value on the tree            assert(v &gt;= 0);            int x = 0;            for (int now = log2(size + 1) + 2; now &gt;= 0; --now) &#123;                if (x + (1 &lt;&lt; now) &lt;= size + 1 &amp;&amp; tr[x + (1 &lt;&lt; now)] &lt; v) &#123;                    x += (1 &lt;&lt; now);                    v -= tr[x];                &#125;            &#125;            return x;        &#125;    &#125;;&#125;namespace segtree &#123;    // tested    template &lt;typename T&gt;    class SegTree &#123;        // range add / range Query    private:        std::vector&lt;T&gt; data;        std::vector&lt;T&gt; lz;        int data_min, data_max;        inline void add(int k, int l, int r, T v) &#123;            data[k] += v * (r - l + 1);            lz[k] += v;        &#125;        inline void pushup(int k) &#123;            data[k] = data[k &lt;&lt; 1] + data[k &lt;&lt; 1 | 1];        &#125;        inline void pushdown(int k, int l, int r, int mid) &#123;            if (lz[k]) &#123;                add(k &lt;&lt; 1, l, mid, lz[k]);                add(k &lt;&lt; 1 | 1, mid + 1, r, lz[k]);                lz[k] = 0;            &#125;        &#125;        void modify(int k, int l, int r, int le, int ri, T v) &#123;            if (l &gt;= le &amp;&amp; r &lt;= ri) return add(k, l, r, v);            int mid = (l + r) &gt;&gt; 1;            pushdown(k, l, r, mid);            if (mid &gt;= le) modify(k &lt;&lt; 1, l, mid, le, ri, v);            if (mid &lt; ri) modify(k &lt;&lt; 1 | 1, mid + 1, r, le, ri, v);            pushup(k);        &#125;        T query(int k, int l, int r, int le, int ri) &#123;            if (l &gt;= le &amp;&amp; r &lt;= ri) return data[k];            int mid = (l + r) &gt;&gt; 1; T res = 0;            pushdown(k, l, r, mid);            if (mid &gt;= le) res += query(k &lt;&lt; 1, l, mid, le, ri);            if (mid &lt; ri) res += query(k &lt;&lt; 1 | 1, mid + 1, r, le, ri);            return res;        &#125;        void build(int k, int l, int r, const std::vector&lt;T&gt;&amp; v, int begin) &#123;            lz[k] = 0;            if (l == r) return data[k] = v[l - data_min + begin], void();            int mid = (l + r) &gt;&gt; 1;            build(k &lt;&lt; 1, l, mid, v, begin);            build(k &lt;&lt; 1 | 1, mid + 1, r, v, begin);            pushup(k);        &#125;        void print(int k, int l, int r) &#123;            std::cerr &lt;&lt; &quot;k = &quot; &lt;&lt; k &lt;&lt; &quot;, l = &quot; &lt;&lt; l &lt;&lt; &quot;, r = &quot; &lt;&lt; r &lt;&lt; &quot;, data = &quot; &lt;&lt; data[k] &lt;&lt; &#x27;\n&#x27;;            if (l == r) return;            int mid = (l + r) &gt;&gt; 1;            pushdown(k, l, r, mid);            print(k &lt;&lt; 1, l, mid);            print(k &lt;&lt; 1 | 1, mid + 1, r);        &#125;    public:        SegTree(int _data_min, int _data_max) :             data((_data_max - _data_min + 2) &lt;&lt; 2, 0),            lz((_data_max - _data_min + 2) &lt;&lt; 2, 0),            data_min(_data_min),            data_max(_data_max) &#123;                // _data_min: lower_bound of data; _data_max: upper_bound of data                assert(_data_max &gt;= _data_min);            &#125;        inline void modify(int le, int ri, T v) &#123;            // add v to all data in [le, ri]            modify(1, data_min, data_max, le, ri, v);        &#125;        inline T query(int le, int ri) &#123;            // query the sum of data in [le, ri]            return query(1, data_min, data_max, le, ri);        &#125;        inline void build(const std::vector&lt;T&gt;&amp; v, int begin) &#123;            // build the tree based on array v from index &#x27;begin&#x27;            assert(int(v.size()) - begin &gt;= data_max - data_min + 1);            build(1, data_min, data_max, v, begin);        &#125;        inline void clear() &#123;            // clear the whole tree            build(std::vector&lt;T&gt;(data_max - data_min + 1), 0);        &#125;        inline void print() &#123;            // print the whole tree            std::cerr &lt;&lt; &quot;Current Tree is :::\n&quot;;            print(1, data_min, data_max);        &#125;    &#125;;&#125;namespace simplemath &#123;    template &lt;typename T&gt;    inline T gcd(T a, T b) &#123;        if (a &lt; b) a ^= b ^= a ^= b;        while (b) &#123;            a %= b;            a ^= b ^= a ^= b;        &#125;        return a;    &#125;    template &lt;typename T&gt;    inline T lcm(T a, T b) &#123;        return a * b / gcd(a, b);    &#125;    using LL = long long;    inline int fpow(int a, int b, int MOD) &#123;        int x = 1;        while (b) &#123;            if (b &amp; 1) x = LL(x) * a % MOD;            a = LL(a) * a % MOD;            b &gt;&gt;= 1;        &#125;        return x;    &#125;    class Factoral &#123;        // calculates factoral related problems    private:        std::vector&lt;int&gt; jc;        std::vector&lt;int&gt; nc;        inline void init() &#123;            jc[0] = 1;            for (int i = 1; i &lt;= size; ++i) jc[i] = LL(jc[i - 1]) * i % MOD;            nc[size] = fpow(jc[size], MOD - 2, MOD);            for (int i = size; i &gt;= 1; --i) nc[i - 1] = LL(nc[i]) * i % MOD;        &#125;    public:        const int MOD;        const int size;        Factoral(int max_n, int _mod) : jc(max_n + 1, 0), nc(max_n + 1, 0), MOD(_mod), size(max_n) &#123;init();&#125;;        inline int C(int x, int y) &#123;            assert(x &gt;= 0 &amp;&amp; y &gt;= 0 &amp;&amp; x &gt;= y &amp;&amp; x &lt;= size);            return LL(jc[x]) * nc[y] % MOD * nc[x - y] % MOD;        &#125;        inline int A(int x, int y) &#123;            assert(x &gt;= 0 &amp;&amp; y &gt;= 0 &amp;&amp; x &gt;= y &amp;&amp; x &lt;= size);            return LL(jc[x]) * nc[x - y] % MOD;        &#125;        inline int fac(int x) &#123;            assert(x &gt;= 0 &amp;&amp; x &lt;= size);            return jc[x];        &#125;        inline int fac_inv(int x) &#123;            assert(x &gt;= 0 &amp;&amp; x &lt;= size);            return nc[x];        &#125;        inline int inv(int x) &#123;            assert(x &gt;= 1 &amp;&amp; x &lt; MOD);            if (x &gt;= size) &#123;                return fpow(x, MOD - 2, MOD);            &#125;            return LL(nc[x]) * jc[x - 1] % MOD;        &#125;    &#125;;&#125;using namespace simplemath;using namespace segtree;using namespace fastio;using namespace bitree;FastIO&lt;1&gt; io;// FastIO&lt;1 &lt;&lt; 16&gt; io;using LL = long long;signed main() &#123;    int t; io &gt;&gt; t;    while (t--) &#123;    &#125;    return 0;&#125;

