#include &lt;cstdio&gt;#include &lt;vector&gt;#include &lt;queue&gt;#include &lt;stdlib.h&gt;//[桃]P  [杀]K  [闪]D  [决斗]F  [南猪入侵]N  [万箭齐发]W  [无懈可击]J  [猪哥连弩]Zusing namespace std;const int N = 11, M = 2001, MAXN = 2e5 + 1;int n, m, remainFP, ne[N];  // n猪数  m牌堆中牌数  remainFP剩余反猪数  ne[]下一只活着的猪bool remainMP = 1, penalize = 0;  // remainMP主猪活着吗  penalize主猪要罚吗queue&lt;char&gt; deskcard;             //牌堆char E;                           //最后一张牌：因为如果牌堆拿完了那就拿最后一张牌class List                        //不会用STL list 写了个非常拉胯的List&#123;public:    int begin;      //第一张    int end;        //最后一张    char v[MAXN];   //牌    int nex[MAXN];  //下一张    int pre[MAXN];  //上一张    void pb(int x)  //将一张牌放到最后    &#123;        if (begin == end &amp;&amp; end == 0)            begin = 1;        nex[end] = end + 1;        pre[end + 1] = end;        v[++end] = x;        nex[end] = 0;    &#125;    void del(int x)  //删除某一张牌    &#123;        if (x == begin)            begin = nex[begin];        if (x == end)            end = pre[end];        nex[pre[x]] = nex[x];        pre[nex[x]] = pre[x];    &#125;    void putcard()  //输出所有牌    &#123;        for (int j = begin; j; j = nex[j]) putchar(v[j]), putchar(&#x27; &#x27;);        puts(&quot;&quot;);    &#125;&#125;;class Pig  //猪&#123;public:    char tag;       //类型  &#x27;Z&#x27;忠猪  &#x27;F&#x27;反猪  &#x27;M&#x27;主猪    char inZP;      //在忠猪眼里它的身份(其实是没有用的)    char inFP;      //在反猪眼里它的身份(其实也是没有用的)    char inMP;      //在主猪眼里它的身份(这是有用的因为,有类反猪)    int HP;         //血量    List handcard;  //手牌    bool jump;      //跳了没    bool zgln;      //有没有猪哥连弩    bool dead;      //死了没&#125; A[N];inline void Jump(int i)  //跳&#123;    A[i].inZP = A[i].inMP = A[i].inFP = A[i].tag, A[i].jump = 1;  //跳了相当于所有猪眼中他都是知道的了&#125;inline void getcard(int i)  //摸一张牌&#123;    if (deskcard.empty())        A[i].handcard.pb(E);  //如果摸完了就摸最后一张    else        A[i].handcard.pb(deskcard.front()), deskcard.pop();  //要不然正常摸&#125;inline int read()  //快读一个int&#123;    int num = 0;    char ch = getchar();    whi