e(a, b);  //如果仍然没血就滚蛋        return;    &#125;    while (remainMP &amp;&amp; remainFP) &#123;        if (!Findcard(b, &#x27;K&#x27;))  //如果b找不到[杀],那么b扣血        &#123;            --A[b].HP;            if (A[b].HP &lt;= 0)                BeP(b);            if (A[b].HP &lt;= 0)                Die(a, b);            return;        &#125;        if (!Findcard(a, &#x27;K&#x27;))  //如果a找不到[杀],那么a扣血        &#123;            --A[a].HP;            if (A[a].HP &lt;= 0)                BeP(a);            if (A[a].HP &lt;= 0)                Die(b, a);  //注意如果a死了伤害来源是b            return;        &#125;    &#125;&#125;inline bool MyP(int cur)  // cur主动用[桃]&#123;    if (A[cur].HP &lt; 4)  //不满就用    &#123;        ++A[cur].HP;        return true;    &#125;    return false;  //满了不用&#125;inline bool MyK(int cur)  // cur主动用[杀]&#123;    if (A[cur].tag == &#x27;Z&#x27; &amp;&amp; A[getne(cur)].inZP == &#x27;F&#x27; || A[cur].tag == &#x27;M&#x27; &amp;&amp; A[getne(cur)].inMP == &#x27;F&#x27; ||        A[cur].tag == &#x27;F&#x27; &amp;&amp; A[getne(cur)].inFP == &#x27;M&#x27; ||        A[cur].tag == &#x27;F&#x27; &amp;&amp; A[getne(cur)].inFP == &#x27;Z&#x27;)  //如果下一个是敌人    &#123;        Jump(cur), K(cur, getne(cur));  //[注意]:用[杀]会跳        return true;    &#125;    return false;  //如果下一个不是敌人那就不杀(废话)&#125;inline bool MyZ(int cur)  // cur主动用[猪哥连弩](最良心的卡)&#123;    A[cur].zgln = 1;  //装备    return true;&#125;inline bool MyF(int cur)  // cur主动用[决斗]&#123;    bool used = 0;    for (int i = getne(cur); i != cur &amp;&amp; remainMP &amp;&amp; remainFP; i = getne(i))  //找到下一个能决斗的    &#123;        if (A[cur].tag == &#x27;Z&#x27; &amp;&amp; A[i].inZP == &#x27;F&#x27; || A[cur].tag == &#x27;M&#x27; &amp;&amp; A[i].inMP == &#x27;F&#x27; ||            A[cur].tag == &#x27;F&#x27; &amp;&amp; A[i].inFP == &#x27;M&#x27;)  //找到目标        &#123;  //[注意]:反猪遇到第一个忠猪不会用[决斗]!因为他会优先考虑主猪!            used = 1;            Jump(cur);  //用[决斗]要跳            F(cur, i);            break;        &#125;    &#125;    return used;