#125;			else if (y1&gt;y2)//如果在下面			&#123;				for (int i=y1-1;inmap(x1,i);--i)				&#123;					if (i==y2) return true;					if (col[x1][i]!=&quot;&quot;) return false;				&#125;			&#125;		&#125;		else if (y1==y2)//如果在同一列		&#123;			if (x1&lt;x2)			&#123;				for (int i=x1+1;inmap(i,y1);++i)				&#123;					if (i==x2) return true;					if (col[i][y1]!=&quot;&quot;) return false;				&#125;			&#125;			else if (x1&gt;x2)			&#123;				for (int i=x1-1;inmap(i,y1);--i)				&#123;					if (i==x2) return true;					if (col[i][y1]!=&quot;&quot;) return false;				&#125;			&#125;		&#125;	&#125;	else if (mp[x1][y1]==&quot;duck&quot;)//鸭	&#123;//鸭看似复杂，实际上就是马在斜着跳一步，有两个马脚而已 		for (int i=0;i&lt;D_duck;++i)		&#123;			int nx=x1+px1_duck[i],ny=y1+py1_duck[i];//第一个马脚 			if (inmap(nx,ny)&amp;&amp;col[nx][ny]==&quot;&quot;)			&#123;				nx=x1+px2_duck[i],ny=y1+py2_duck[i];//第二个马脚 				if (inmap(nx,ny)&amp;&amp;col[nx][ny]==&quot;&quot;)				&#123;					nx=x1+dx_duck[i],ny=y1+dy_duck[i];					if (nx==x2&amp;&amp;ny==y2) return true;//到达 				&#125;			&#125;		&#125;	&#125;	else if (mp[x1][y1]==&quot;soldier&quot;)//兵 	&#123;//兵和王和士没有本质区别 		for (int i=0;i&lt;D_soldier;++i)		&#123;			int nx=x1+dx_soldier[i],ny=y1+dy_soldier[i];			if (nx==x2&amp;&amp;ny==y2) return true;		&#125;	&#125;	return false;&#125;inline bool JJ()//判断将军 &#123;	for (int i=0;i&lt;N;++i)		for (int j=0;j&lt;M;++j)			if (mp[i][j]==&quot;captain&quot;)//暴力搜索出王 				for (int k=0;k&lt;N;++k)					for (int h=0;h&lt;M;++h)//再暴力枚举每一个点						if (pd(k,h,i,j,0))//如果可以到达，那就将军了，你也不用管将哪个军 							return true;	return false;&#125;inline void output(int x1,int y1,int x2,int y2)//可行时输出 &#123;	put(col[x1][y1]),putchar(&#x27; &#x27;),put(mp[x1][y1]),putchar(&#x27;;&#x27;);//输出在哪个点 	if (col[x2][y2]==&quot;&quot;) put(&quot;NA;&quot;);//如果终点没有棋就输出NA 	else put(col[x2][y2]),putchar(&#x27; &#x27;),put(mp[x2][y2]),putchar(&#x27;;&#x27;);//不然吃掉 	if (mp[x2][y2]==&quot;captain&quot;) GG=1;//如果终点是王即王被吃掉了，那就GG 	col[x2][y2]=col[x1][y1];	mp[x2][y2]=mp[x1][y1];	col[x1][y1]=mp[x1][y1]=&quot;&quot;;//移动 	if (JJ()) put(&quot;yes;&quot;);//[注意]:一定要移动完了再判断将军 	else put(&quot;no;&quot;);//判断将军 	if (GG) put(&quot;yes&quot;);//判断游戏结束 	else put(&quot;no&quot;);	puts(&quot;&quot;);&#125;inline int read()//快读 &#123;	int num=0;char ch=getchar();	while (ch&gt;&#x27;9&#x27;||ch&lt;&#x27;0&#x27;) ch=getchar();	while (ch&lt;=&#x27;9&#x27;&amp;&amp;ch&gt;=&#x27;0&#x27;) num=(num&lt;&lt;1)+(num&lt;&lt;3)+(ch^48),ch=getchar();	return num;&#125;int main()&#123;	Q=read();//输入 	while (Q--)	&#123;		int x1=read(),y1=read(),x2=read(),y2=read();		if (!pd(x1,y1,x2,y2,1)) puts(&quot;Invalid command&quot;);//如果没办法移动就输出错误 		else output(x1,y1,x2,y2),Round=Round==&quot;red&quot;?&quot;blue&quot;:&quot;red&quot;;//要不然就output并转换回合 	&#125;&#125;

普通BST(Binary Search Tree)：一种二叉树，保证所有节点的值都比左儿子大（如有），且比右儿子小（如有）。这样，这种二叉树的前序遍历就一定是一个递增序列。
在随机情况下，这个数据结构的表现非常好，但是有心人总喜欢卡它，比如说这道题就过不去：
https://www.luogu.com.cn/problem/P3369

Show Code
#include&lt;bits/stdc++.h&gt;using namespace std;const int N = 100001, INF = 1e7 + 1;int rt, son[N][2]/*两个儿子*/,         val[N]/*当前节点值*/,         cnt[N]/*当前节点个数*/,         sz[N]/*当前节点子树内个数*/,         tot/*总结点数*/;inline int newnode(int x)&#123; // 加新点    val[++tot] = x;    cnt[tot] = 1;    sz[tot] = 1;    return tot;&#125;inline void pushup(int x)&#123; // 更新节点信息    sz[x] = sz[son[x][0]] + sz[son[x][1]] + cnt[x];&#125;int Insert(int u, int x)&#123; // 插入节点，值为x    if (!u) return newnode(x);    if (val[u] == x) return ++cnt[u], u; // 多个表达式用逗号连接，返回最后一个。    if (val[u] &lt; x) son[u][1] = Insert(son[u][1], x);    else son[u][0] = Insert(son[u][0], x);    return pushup(u), u;&#125;void Delete(int u, int x)&#123; // 删除值为x的节点    if (val[u] == x) --cnt[u];    else if (val[u] &lt; x) Delete(son[u][1], x);    else Delete(son[u][0], x);    return pushup(u);&#125;int Rank(int u, int x)&#123; // 查询x是第几大的节点    if (!u) return 1;    if (val[u] &lt; x) return sz[son[u][0]] + cnt[u] + Rank(son[u][1], x);    else if (val[u] == x) return sz[son[u][0]] + 1;    else return Rank(son[u][0], x);&#125;int QueryK(int u, int k)&#123; // 查询排名为k的数    if (k &lt;= sz[son[u][0]]) return QueryK(son[u][0], k);    if (k &lt;= sz[son[u][0]] + cnt[u]) return val[u];    return QueryK(son[u][1], k - sz[son[u][0]] - cnt[u]);&#125;signed main()&#123;    int n; scanf(&quot;%d&quot;, &amp;n);    while (n--)&#123;        int opt, x; scanf(&quot;%d%d&quot;, &amp;opt, &amp;x);        if (opt == 1) rt = Insert(rt, x);        else if (opt == 2) Delete(rt, x);        else if (opt == 3) printf(&quot;%d\n&quot;, Rank(rt, x));        else if (opt == 4) printf(&quot;%d\n&quot;, QueryK(rt, x));        else if (opt == 5) printf(&quot;%d\n&quot;, QueryK(rt, Rank(rt, x) - 1));        else if (opt == 6) printf(&quot;%d\n&quot;, QueryK(rt, Rank(rt, x + 1)));    &#125;    return 0;&#125;

